"""Build static, crawlable pages. Python standard library only."""
import json, re, unicodedata
from pathlib import Path
from html import escape as e
ROOT=Path(__file__).resolve().parents[1]
def read(p): return (ROOT/p).read_text()
def write(p,s):
 p=ROOT/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
def slug(s):return re.sub(r'[^a-z0-9]+','-',unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()).strip('-')
items=json.loads(read('data/catalogue.json'));logos=json.loads(read('data/brandLogos.json'));sources=json.loads(read('data/toolSources.json'))
base='https://thiagollipe-web.github.io/t.free/'
kind_labels={'app':'Aplicativo','agent':'Agente','runtime':'Ambiente de execução','service':'Serviço online'}
execution_labels={'hosted':'No site do provedor','local':'No seu computador','hybrid':'Ambiente próprio + modelo local ou API','api':'Plataforma de API','self-hosted':'Hospedagem própria'}
def review_date(a):return '/'.join(reversed(a['reviewedAt'].split('-')))
categories=list(dict.fromkeys(a['category'] for a in items))
guides=json.loads(read('data/guides.json'))
easy={'ChatGPT','Gemini','Claude','Perplexity','Duck.ai','Microsoft Copilot','Mistral Vibe','DeepSeek','Qwen'}
for a in items:
 a['slug']=slug(a['name']);a['easy']=a.get('easy',a['name'] in easy);a['source']=a.get('source',sources.get(a['name'],a['url']));a['kindLabel']=kind_labels[a['kind']];a['executionLabel']=execution_labels[a['execution']];a['conditions']=a.get('conditions',' · '.join(a['tags'])+'. Confira as regras, cotas e condições no provedor.')
def meta(title,desc,path):return f'''<title>{e(title)}</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{base+path}"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><meta property="og:site_name" content="T.Free"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{base+path}"><meta property="og:image" content="{base}assets/social.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml">'''
def card(a,prefix=''):
 return f'''<article class="card" data-name="{e(a['name'])}" data-kind="{a['kind']}" data-category="{e(a['category'])}" data-easy="{str(a['easy']).lower()}" data-search="{e(' '.join([a['name'],a['category'],a['description'],a.get('keywords',''),*a['tags'],*a['aliases'],*[x['name'] for x in a['alternativesTo']]]))}"><div class="card-top"><div class="icon"><img src="{prefix+logos[a['name']]}" width="32" height="32" alt="" loading="lazy" decoding="async"></div><div><h3><a class="tool-title" href="{prefix}ferramentas/{a['slug']}/">{e(a['name'])}</a></h3><span class="category">{e(a['category'])} · {e(a['kindLabel'])}</span></div></div><p>{e(a['description'])}</p><div class="tags">{''.join('<span class="tag'+(' free' if i==0 else '')+'">'+e(t)+'</span>' for i,t in enumerate(a['tags']))}</div><details class="tool-details"><summary>Condições e fonte</summary><p>{e(a['conditions'])}</p><a href="{e(a['source'])}" target="_blank" rel="noopener noreferrer">Consultar fonte oficial ↗</a></details><a class="card-link" href="{prefix}ferramentas/{a['slug']}/">Ver ficha <span aria-hidden="true">↗</span></a><label class="compare-pick" hidden><input type="checkbox" value="{a['slug']}" aria-label="Comparar {e(a['name'])}"> Comparar</label></article>'''
nav='''<header><nav class="wrap" aria-label="Navegação principal"><a href="{prefix}index.html" class="brand"><img src="{prefix}assets/caramelo.svg" alt="" width="39" height="39">T.Free<b>↗</b></a><div class="nav-right"><a class="nav-search" href="{prefix}index.html#search">⌕ Buscar ferramenta</a><a href="{prefix}index.html#catalogue">Catálogo</a><a href="{prefix}index.html#guia" class="desktop">Guias em português</a><a class="nav-guide" href="{prefix}index.html#sobre" aria-label="Sobre o T.Free">?</a></div></nav></header>'''
footer='''<footer><div class="wrap foot-row"><span><strong>T.Free ↗</strong> &nbsp; Feito para explorar possibilidades.</span><span>Marcas pertencem aos respectivos titulares · Sem vínculo oficial · Condições sujeitas a mudanças · Revisão: 30/10/2026</span></div></footer>'''
context={
'Agentes':('Automatizar tarefas com modelos e ferramentas configurados por você','Comece por uma tarefa pequena e reversível. Leia a documentação, confira as permissões e valide cada integração antes de usar dados reais.','O software do agente pode ser gratuito, mas modelo, APIs, hospedagem e serviços externos podem cobrar. Não conceda permissões amplas nem compartilhe credenciais sem necessidade.'),
'Chat':('Escrever, organizar ideias e esclarecer dúvidas','Experimente uma tarefa pequena: peça um roteiro, forneça o contexto e revise a resposta. Compare clareza, qualidade em português e facilidade de corrigir o resultado.','Não trate uma resposta convincente como prova. Confirme fatos nas fontes e evite enviar dados pessoais ou profissionais.'),
'Local/Offline':('Explorar modelos no próprio computador','Verifique sistema operacional, memória e espaço antes de instalar. Comece por um modelo pequeno e um texto de teste, sem informações sensíveis.','Software local não significa custo zero: hardware, energia e licença do modelo continuam importantes. Recursos remotos podem ter políticas diferentes.'),
'API/Dev':('Experimentar modelos em projetos de desenvolvimento','Faça um protótipo pequeno, defina um limite de consumo e leia as regras do modelo escolhido. Proteja credenciais em um servidor, nunca no HTML público.','Uma faixa gratuita pode ter cotas, restrições de região ou condições de dados. O catálogo não fornece créditos nem inclui os custos de hospedagem.'),
'Imagem':('Criar e explorar ideias visuais','Descreva objetivo, composição e formato. Teste uma imagem simples antes de investir créditos e verifique como funciona o download.','Compare resolução, visibilidade pública, créditos, marcas-d’água e direitos de uso. Gratuidade não garante licença comercial.'),
'Áudio':('Experimentar voz, som e música','Use um texto curto ou um trecho de teste para entender o resultado. Confira formato, duração e exportação antes de começar um projeto maior.','Verifique direitos sobre vozes, músicas e arquivos enviados. Confira a licença comercial separadamente do acesso gratuito.'),
'Vídeo':('Editar e preparar conteúdo em vídeo','Comece com um clipe curto e teste legenda, formato e exportação. Confira se os recursos que você precisa pertencem ao plano gratuito.','Resolução, marca-d’água, biblioteca de mídia e funções de IA podem ter condições distintas.'),
'Design':('Transformar uma ideia em uma peça visual','Escolha o formato final, prepare seu texto e teste um modelo simples. Revise legibilidade e contraste antes de exportar.','Elementos premium e recursos de IA podem ter cotas próprias. Verifique a licença de cada ativo usado.'),
'Estudos':('Estudar com apoio de suas próprias fontes','Selecione um material que você tem autorização para usar e peça um resumo com referências. Volte aos trechos originais para conferir a explicação.','Evite dados de alunos e documentos pessoais. Um resumo automatizado pode omitir contexto ou interpretar incorretamente o material.'),
'Pesquisa':('Descobrir literatura e organizar referências','Comece com uma pergunta específica. Use as sugestões para localizar os artigos e registre os critérios da sua busca.','Leia metodologia, amostra e limitações no artigo original. Resumos, conexões e citações automáticas precisam de conferência.'),
'Escrita':('Revisar um texto sem perder a sua intenção','Teste um parágrafo e compare a sugestão com o original. Confira tom, significado, concordância e vocabulário em português.','Uma reescrita pode alterar o sentido. Limites de caracteres e recursos disponíveis variam; evite textos confidenciais.'),
'Código':('Apoiar o desenvolvimento de software','Use uma tarefa pequena e verificável. Leia o código sugerido, rode testes e examine as dependências antes de integrar ao projeto.','Editor, extensão e modelo são componentes diferentes. Um assistente gratuito pode conectar-se a uma API paga.'),
'Busca':('Encontrar informações com referências','Formule uma pergunta específica, abra os links citados e confira datas e autoria. Compare fontes independentes quando a decisão for importante.','Respostas de busca podem sintetizar incorretamente uma fonte. Não use a resposta automática como única evidência.')}
html=read('templates/base.html')
html=html.replace('HERO_LOGOS',''.join(f'<a href="ferramentas/{a["slug"]}/" aria-label="Conhecer {e(a["name"])}"><img src="{logos[a["name"]]}" alt="" width="28" height="28"></a>' for a in [items[i] for i in [32,33,34,0,2,10]])+'<a href="#catalogue" aria-label="Explorar todas as 35 ferramentas">+29</a>')
html=re.sub(r'<title>.*?</title>\s*<meta name="description"[^>]+>',meta('T.Free — Ferramentas de IA gratuitas em português','Encontre 32 ferramentas de IA com opções gratuitas. Compare chat, imagens, escrita e modelos locais, com limites explicados e links oficiais.',''),html)
html=re.sub(r'<header>.*?</header>',nav.format(prefix=''),html,flags=re.S)
html=re.sub(r'<div class="mini-strip">.*?</div>','<div class="mini-strip"><span><strong id="total">32</strong> ferramentas selecionadas</span><span><strong>Sem cadastro</strong> para explorar</span><span><strong>Fontes oficiais</strong> e limites claros</span><span><strong>Em português</strong> do começo ao fim</span></div>',html)
html=html.replace('<div class="grid" id="grid"></div>','<div class="grid" id="grid">'+''.join(card(a) for a in items)+'</div><p id="empty" class="empty" hidden>Nenhuma ferramenta encontrada. Tente outra palavra ou limpe os filtros.</p>')
html=html.replace('<div class="filters" id="filters" aria-label="Filtrar por categoria"></div>','<div class="filters" id="filters" aria-label="Filtrar por categoria" hidden></div><div class="category-links" aria-label="Páginas por categoria">'+''.join(f'<a href="categorias/{slug(c)}/">{e(c)}</a>' for c in categories)+'</div>')
html=html.replace('<div class="category-links"', '<p class="category-links-title">Explorar páginas por categoria</p><div class="category-links"')
html=html.replace('<div class="searchbox">','<div class="searchbox" hidden>')
html=html.replace('<div class="count" id="count" role="status" aria-live="polite"></div>','<div class="count" id="count" role="status" aria-live="polite">32 ferramentas para explorar</div>')
html=html.replace('<p class="notice">','<section class="compare-toolbar" id="comparison" aria-label="Comparar ferramentas" hidden><div><strong>Sua seleção</strong><p id="compare-status" role="status">Selecione de 2 a 3 ferramentas.</p></div><button type="button" id="compare-open" disabled>Comparar seleção</button><button type="button" id="compare-clear">Limpar seleção</button><div id="compare-result" hidden></div></section><p class="notice">',1)
html=re.sub(r'<footer>.*?</footer>',footer.format(prefix=''),html,flags=re.S)
html=html.replace('id="chat-toggle"','id="chat-toggle" hidden')
html=html.replace('O aplicativo inteiro','O catálogo').replace('O catálogo funciona offline;', 'O catálogo baixado com seus arquivos funciona offline;')
html=html.replace('<section class="about" id="guia"', '<section class="prose"><div class="eyebrow">LEITURA RÁPIDA · ESCOLHAS MELHORES</div><h2>Guias para começar sem confusão</h2><ul class="resource-links">'+''.join('<li><a href="guias/'+g['slug']+'/">'+e(g['title'])+'</a></li>' for g in guides)+'</ul></section><section class="about" id="guia"')
html+='\n<script src="assets/catalogue.js" defer></script><script src="assets/chat.js" defer></script></body></html>'
html=html.replace('32 ferramentas',str(len(items))+' ferramentas').replace('id="total">32<','id="total">'+str(len(items))+'<').replace('Revisão: 30/10/2026','Datas e fontes nas fichas').replace('Referências revisadas em 30/10/2026;', 'Datas e referências nas fichas;')
write('index.html',html)
# Data is compiled into JS; the website makes no external request to search or compare.
write('assets/catalogue.js','const catalogue='+json.dumps(items,ensure_ascii=False)+';\n'+read('templates/catalogue.js'))
paths=['']
def page(title,desc,path,content):
 prefix='../../';return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4c95b">'+meta(title,desc,path)+'<link rel="stylesheet" href="../../assets/legacy.css"><link rel="stylesheet" href="../../assets/redesign.css"><link rel="stylesheet" href="../../assets/caramelo.css"></head><body><a class="skip" href="#conteudo">Pular para o conteúdo</a>'+nav.format(prefix=prefix)+'<main class="wrap" id="conteudo">'+content+'</main>'+footer.format(prefix=prefix).replace('Revisão: 30/10/2026','Datas e fontes nas fichas')+'</body></html>'
for c in categories:
 path='categorias/'+slug(c)+'/';subset=[a for a in items if a['category']==c];use,start,caution=context[c]
 content=f'<nav class="breadcrumbs" aria-label="Localização"><a href="../../">Início</a> / {e(c)}</nav><section class="detail-hero"><div class="eyebrow">EXPLORE POR CATEGORIA</div><h1>Ferramentas de IA para {e(c.lower())}</h1><p class="lead">{e(use)}. Veja opções, condições de acesso e fontes oficiais para escolher com mais clareza.</p></section><section class="prose"><h2>Por onde começar</h2><p>{e(start)}</p><p>{e(caution)}</p></section><div class="grid">'+''.join(card(a,'../../') for a in subset)+'</div>'
 write(path+'index.html',page('IA para '+c+' — opções gratuitas e limites | T.Free',use+'. Compare ferramentas, limites e fontes oficiais no T.Free.',path,content));paths.append(path)
for a in items:
 path='ferramentas/'+a['slug']+'/';use,start,caution=context[a['category']];related=[b for b in items if b['category']==a['category'] and b!=a][:3]
 crumbs=[{'@type':'ListItem','position':1,'name':'Início','item':base},{'@type':'ListItem','position':2,'name':a['category'],'item':base+'categorias/'+slug(a['category'])+'/'},{'@type':'ListItem','position':3,'name':a['name'],'item':base+path}]
 content=f'''<nav class="breadcrumbs" aria-label="Localização"><a href="../../">Início</a> / <a href="../../categorias/{slug(a['category'])}/">{e(a['category'])}</a> / {e(a['name'])}</nav><section class="detail-hero"><div class="eyebrow">FERRAMENTA · {e(a['category'])}</div><h1>{e(a['name'])}</h1><p class="lead">{e(a['description'])}</p><div class="hero-actions"><a class="button" href="{e(a['url'])}" target="_blank" rel="noopener noreferrer">Abrir site oficial ↗</a><a href="../../#catalogue">Voltar ao catálogo</a></div></section><div class="detail-layout"><article class="prose"><h2>{e(a['name'])} é gratuito?</h2><p>{e(a['conditions'])}</p><p>O acesso descrito não é garantia de uso ilimitado. Confira a disponibilidade e as regras atuais no provedor antes de começar.</p><h2>Software, modelo e infraestrutura</h2><dl class="cost-breakdown"><dt>Tipo</dt><dd>{e(a['kindLabel'])}</dd><dt>Modo de execução</dt><dd>{e(a['executionLabel'])}</dd><dt>Software</dt><dd>{e(a['costs']['software'])}</dd><dt>Modelo / API</dt><dd>{e(a['costs']['model'])}</dd><dt>Infraestrutura</dt><dd>{e(a['costs']['hosting'])}</dd></dl><p><strong>Dependências a considerar:</strong> {e(' · '.join(a['costs']['dependencies']) or 'Consulte as condições do provedor.')}</p><h2>Como avaliar na prática</h2><p>{e(start)}</p><h2>O que observar antes de usar</h2><p>{e(caution)}</p><h2>Fontes e transparência</h2><p><a href="{e(a['source'])}" target="_blank" rel="noopener noreferrer">Consultar as informações oficiais sobre {e(a['name'])} ↗</a></p><p>Referências editoriais desta ferramenta: {review_date(a)}. Esta ficha não representa um novo teste do produto. Condições podem mudar; a fonte oficial prevalece.</p><p>O T.Free organiza informações públicas e não fornece este serviço. Não há parceria ou endosso implícito.</p></article><aside class="detail-sidebar"><img src="../../{logos[a['name']]}" alt="" width="56" height="56"><h2>Resumo da escolha</h2><dl><dt>Categoria</dt><dd>{e(a['category'])}</dd><dt>Tipo de acesso</dt><dd>{e(' · '.join(a['tags']))}</dd><dt>Como começar</dt><dd>{'Direto no navegador; consulte exigências de conta.' if a['easy'] else 'Consulte requisitos de instalação ou configuração no provedor.'}</dd></dl><a href="../../categorias/{slug(a['category'])}/">Ver opções da categoria →</a></aside></div>'''
 if a['alternativesTo']:content+='<section class="prose"><h2>Alternativas para tarefas semelhantes</h2><p>Relações editoriais por finalidade, não equivalência completa nem economia garantida.</p><ul>'+''.join('<li><strong>'+e(x['name'])+'</strong>: '+e(x['scope'])+'</li>' for x in a['alternativesTo'])+'</ul></section>'
 if related:content+='<section class="prose"><h2>Outras opções para explorar</h2></section><div class="grid">'+''.join(card(b,'../../') for b in related)+'</div>'
 content+='<script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':crumbs},ensure_ascii=False)+'</script>'
 write(path+'index.html',page(a['name']+' é gratuito? Limites e como usar | T.Free',a['description']+' Consulte condições de acesso e fonte oficial.',path,content));paths.append(path)
for g in guides:
 path='guias/'+g['slug']+'/'
 content='<nav class="breadcrumbs" aria-label="Localização"><a href="../../">Início</a> / Guias</nav><section class="detail-hero"><div class="eyebrow">GUIA T.FREE</div><h1>'+e(g['title'])+'</h1><p class="lead">'+e(g['intro'])+'</p></section><article class="prose">'+''.join('<p>'+e(p)+'</p>' for p in g['paragraphs'])+'<h2>Fontes oficiais</h2><ul>'+''.join('<li><a href="'+e(url)+'" target="_blank" rel="noopener noreferrer">'+e(label)+' ↗</a></li>' for label,url in g['sources'])+'</ul><p>Referências verificadas em 31/10/2026. Condições podem mudar; consulte o provedor antes de usar.</p><p><a href="../../#catalogue">Explore as ferramentas do catálogo →</a></p></article>'
 write(path+'index.html',page(g['title']+' | T.Free',g['intro'],path,content));paths.append(path)
write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+base+p+'</loc></url>' for p in paths)+'</urlset>')
write('.nojekyll','')
print('Built',len(paths),'indexable pages and sitemap')
